import{_ as a,o,c as t,a2 as s}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"QEMU 调试技术","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/qemu-debugging.md","filePath":"zh/troubleshooting/qemu-debugging.md"}'),d={name:"zh/troubleshooting/qemu-debugging.md"};function n(i,e,c,l,p,r){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="qemu-调试技术" tabindex="-1">QEMU 调试技术 <a class="header-anchor" href="#qemu-调试技术" aria-label="Permalink to &quot;QEMU 调试技术&quot;">​</a></h1><p>捕获一切、盯住整机（而不只是客户机）、挂上 gdb、并了解勘误 — QEMU 自身的怪癖在&quot;OS bug&quot;中占了 惊人的份额。</p><h2 id="捕获一切" tabindex="-1">捕获一切 <a class="header-anchor" href="#捕获一切" aria-label="Permalink to &quot;捕获一切&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -serial file:boot.log -display none \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span></code></pre></div><p>串口日志就是引导叙事 — 每个子系统一行 <code>OK</code>、panic 横幅、寄存器转储、crashlog 刷写。串口控制台是 <strong>权威</strong>（VGA 尽力而为：panic 单行用 <code>Registers and call trace on the serial console.</code> 把你指回串口）。</p><p>对三重故障 / 复位循环：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-d int,cpu_reset,guest_errors -D qemu.log</span></span></code></pre></div><p>日志显示最后一次中断/复位；boot.log 中&quot;最后一条 没有打印 OK 的自测行&quot;指名死去的阶段。</p><h2 id="交互式串口-monitor" tabindex="-1">交互式串口 + monitor <a class="header-anchor" href="#交互式串口-monitor" aria-label="Permalink to &quot;交互式串口 + monitor&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 ... -serial stdio -monitor stdio</span></span></code></pre></div><p>在同一个终端上给出客户机控制台与 QEMU monitor（E2E 运行器用 <code>mon:stdio</code>；前缀 <code>@</code> 的命令送往 monitor）。要送入串口链路无法承载的按键：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(qemu) sendkey ctrl-alt-f2      # OCSE GUI&lt;-&gt;CLI switch</span></span>
<span class="line"><span>(qemu) sendkey up               # menu navigation (PS/2 path)</span></span>
<span class="line"><span>(qemu) sendkey f2               # editor IME toggle</span></span>
<span class="line"><span>(qemu) screendump shot.ppm      # VGA proof (see errata first!)</span></span></code></pre></div><p><code>sendkey</code> 是方向键/F 键的注入路径：TCP 串口套接字上的 CSI 字节在引导菜单时刻到达得太晚。指针输入 需要 QMP <code>input-send-event</code>（HMP <code>mouse_move</code> 在 <code>-display none</code> + QEMU 10 上已死）。</p><h2 id="gdb-进入内核" tabindex="-1">GDB 进入内核 <a class="header-anchor" href="#gdb-进入内核" aria-label="Permalink to &quot;GDB 进入内核&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 ... -s -S        # gdb stub, frozen at reset</span></span>
<span class="line"><span>gdb build/opencube_base.elf          # the pre-strip ELF has symbols</span></span>
<span class="line"><span>(gdb) target remote localhost:1234</span></span>
<span class="line"><span>(gdb) break kmain</span></span>
<span class="line"><span>(gdb) continue</span></span></code></pre></div><p><code>build/opencube_base.elf</code> 由 <code>make kernel</code> 保留正是为了 这个 — 最终的 <code>build/opencube.elf</code> 已被 strip。</p><h2 id="确定性重放" tabindex="-1">确定性重放 <a class="header-anchor" href="#确定性重放" aria-label="Permalink to &quot;确定性重放&quot;">​</a></h2><p>构建是可复现的（<code>make reproducible-check</code>）：同一棵树 产出逐字节相同的 ELF，因此你能复现两次的崩溃 两次都是同样的字节。配合 <code>-icount</code> 获得网络测试的时序 稳定。</p><h2 id="qemu-勘误清单" tabindex="-1">QEMU 勘误清单 <a class="header-anchor" href="#qemu-勘误清单" aria-label="Permalink to &quot;QEMU 勘误清单&quot;">​</a></h2><p>针对本项目验证过的怪癖 — 责怪内核之前先查这些：</p><table tabindex="0"><thead><tr><th>勘误</th><th>影响</th><th>规避</th></tr></thead><tbody><tr><td>QEMU 10 的 <code>intel-hda</code> 模型在 44.1 kHz 上死循环</td><td>该采样率下音频冻结（真实硬件正常；源内有记载）</td><td>其他采样率，或 <code>-device AC97</code>/<code>-device sb16</code></td></tr><tr><td>QEMU 在 HMP <code>screendump</code> 之后丢弃串口 RX 字节</td><td>随后几秒输入抖动（经内核内 RX 追踪验证）</td><td>绝不在功能轮次中途截图；抖动的检查隔离重跑</td></tr><tr><td>HMP <code>mouse_move</code> 在 <code>-display none</code> + QEMU 10 上已死</td><td>GUI 测试无法移动指针</td><td>QMP <code>input-send-event</code></td></tr><tr><td>串口回显与客户机输出重叠</td><td>吃掉 <code>e</code> 的 <code>ega]</code> 伪影；错位片段</td><td>容错匹配（把 <code>[tag]</code> 括号视为可选，剥离回显行）；见 <a href="./silent-failures.html">silent-failures.md</a> §8</td></tr><tr><td>TCG（无 KVM）RSA-2048 超过 500 s</td><td>sshd 首启密钥生成看似挂起</td><td>预置 <code>etc.img</code>（<code>tools/host_keygen_etc.py</code>）；宽裕超时（横幅 420 s）</td></tr><tr><td>默认 <code>pc</code> 机器无 Intel TCO</td><td><code>watchdog hw: none</code>（如实） — q35 的 ICH9-LPC 有</td><td>TCO 测试用 <code>-machine q35</code></td></tr><tr><td>user-net 无射频</td><td><code>wifi scan</code> 如实报告无射频</td><td>跳过，或物理硬件</td></tr><tr><td>El Torito <code>-boot-info-table</code></td><td>将引导镜像的字节 8..0x47 清零 — OCBL stage1 入口代码被毁（静默挂起 + 串口上 5 MB 的 0x00）</td><td>绝不对 OCBL ISO 启用它（<code>build_test_iso.py</code> 刻意省略它）</td></tr></tbody></table><h2 id="设备矩阵速览" tabindex="-1">设备矩阵速览 <a class="header-anchor" href="#设备矩阵速览" aria-label="Permalink to &quot;设备矩阵速览&quot;">​</a></h2><p>点亮各驱动家族的 QEMU flag 已制表于 <a href="./../drivers/storage.html">驱动手册</a> — 挂上你正在调试的那个确切设备。常备优选：</p><ul><li><code>-device e1000,netdev=n1</code> + <code>-netdev user,id=n1</code> — 测试最充分的 NIC。</li><li><code>-device virtio-net-pci</code> — virtio 路径（当心 TX 超时）。</li><li><code>-drive file=hd.img,format=raw</code> — 磁盘；<code>readonly=on</code> 产生如实的 <code>virtio-blk: write rejected</code>（按设计）。</li><li><code>-device intel-hda</code> / <code>AC97</code> / <code>sb16</code> — 音频。</li><li><code>-machine q35</code> — TCO watchdog、ICH9 LPC。</li></ul><h2 id="双实例链路" tabindex="-1">双实例链路 <a class="header-anchor" href="#双实例链路" aria-label="Permalink to &quot;双实例链路&quot;">​</a></h2><p>共享 <code>-netdev socket,multicast=...</code> 为 NIC/SSH 测试提供真实双节点链路；端口转发（<code>-netdev user,id=n1,hostfwd=tcp::2223-:22</code>）让宿主 paramiko 客户端接到 客户机 <code>sshd 22</code>。</p><h2 id="截图管线" tabindex="-1">截图管线 <a class="header-anchor" href="#截图管线" aria-label="Permalink to &quot;截图管线&quot;">​</a></h2><p><code>make shot-bios</code> / <code>make shot-uefi</code>（VNC + monitor screendump → 经 PIL 转 PNG，<code>tools/qemu_shot_vnc.py</code>）；<code>tools/qemu_snap.py</code> 启动 ISO、对 VGA 截屏、把 80×25 网格渲染为 ASCII。屏幕内容 断言必须检查 ≥ 2 种颜色与可测量的前景占比 （BUG #66：没有机器断言就绝不信&quot;它渲染出来了&quot;）。</p><h2 id="monitor-套接字与裸串口" tabindex="-1">monitor 套接字与裸串口 <a class="header-anchor" href="#monitor-套接字与裸串口" aria-label="Permalink to &quot;monitor 套接字与裸串口&quot;">​</a></h2><p>脚本化控制时，把 monitor 和串口放在 unix 套接字上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 ... \\</span></span>
<span class="line"><span>    -serial unix:serial.sock,server,nowait \\</span></span>
<span class="line"><span>    -monitor unix:mon.sock,server,nowait</span></span></code></pre></div><ul><li>裸控制字节（<code>fix1_before_*</code> 捕获）需要 unix 套接字 chardev 才能让字节<strong>原样</strong>到达 — TCP 串口链路会破坏 时序并在引导菜单时刻吃字符。</li><li><code>socat - UNIX-CONNECT:mon.sock</code> 给你 monitor； <code>sendkey</code>、<code>screendump</code>、<code>pmemsave</code>、设备热插拔都在那里可用。</li><li>事后剖析的内存转储：<code>(qemu) pmemsave 0xb8000 4000 vga.bin</code>（VGA 文本单元 — OCIRE 滚动证明的原理， 无需 OCR）。</li><li>从 monitor 做设备排查：<code>info pci</code>、<code>info block</code>、<code>info usb</code>；热插拔可在不重启宿主机的情况下二分 探针失败。</li></ul><h2 id="sendkey-手册" tabindex="-1">sendkey 手册 <a class="header-anchor" href="#sendkey-手册" aria-label="Permalink to &quot;sendkey 手册&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(qemu) sendkey up            # OCBL menu: entry up (also serial CSI ESC[A)</span></span>
<span class="line"><span>(qemu) sendkey down           # entry down</span></span>
<span class="line"><span>(qemu) sendkey ret            # select</span></span>
<span class="line"><span>(qemu) sendkey f2             # editor IME toggle / TUI save-config</span></span>
<span class="line"><span>(qemu) sendkey f5             # TUI repaint</span></span>
<span class="line"><span>(qemu) sendkey esc            # leave a TUI page</span></span>
<span class="line"><span>(qemu) sendkey ctrl-alt-f1    # OCSE GUI &lt;-&gt; CLI switch</span></span>
<span class="line"><span>(qemu) sendkey ctrl-alt-f2    # the other direction</span></span></code></pre></div><p>规则：PS/2 是注入路径（串口上的 CSI 字节在菜单 时刻到达得太晚）；组合键用连字符（<code>ctrl-alt-f2</code>）； OCBL 菜单本身按契约只认 Up/Down/Enter，外加 供无头自动化使用的串口 CSI 镜像。</p><h2 id="解读-boot-log-—-一个实例" tabindex="-1">解读 boot.log — 一个实例 <a class="header-anchor" href="#解读-boot-log-—-一个实例" aria-label="Permalink to &quot;解读 boot.log — 一个实例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[    0.000] BOOT: OK</span></span>
<span class="line"><span>[    0.412] KM_AIN_ENTERED: OK</span></span>
<span class="line"><span>[    1.208] SCHED_READY: OK</span></span>
<span class="line"><span>[    2.017] DRIVERS_READY: FAIL      &lt;-- died here</span></span></code></pre></div><p>FAIL 行指名阶段；其上最后一条驱动行指名 设备。对照 <a href="./boot-failures.html">boot-failures.md</a> §1 的阶段 阶梯；OCBL 侧按同样的阶段判定这次 引导（30 s 启动 / 10 s 阶段预算，RTC 静默 ≥ 8 s = 失败）。同一日志中的 panic 横幅意味着 内核回收了一条记录 — 下次启动检查 <code>crashlog</code>。</p><h2 id="确定性与可复现性" tabindex="-1">确定性与可复现性 <a class="header-anchor" href="#确定性与可复现性" aria-label="Permalink to &quot;确定性与可复现性&quot;">​</a></h2><ul><li><code>make reproducible-check</code> 验证逐字节相同的输出。</li><li>同一棵树 + 同样 flag = 同样的崩溃：按构建二分，不要 猜。</li><li>时序稳定的网络轮次用 <code>-icount</code>（TCP 套件依赖 它）；搭配 <code>-rtc base=utc</code> 让依赖时钟的测试保持清醒 （否则 X509_E_EXPIRED / NOT_YET 就是陷阱）。</li></ul><h2 id="替你驱动-qemu-的-make-目标" tabindex="-1">替你驱动 QEMU 的 make 目标 <a class="header-anchor" href="#替你驱动-qemu-的-make-目标" aria-label="Permalink to &quot;替你驱动 QEMU 的 make 目标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>作用</th></tr></thead><tbody><tr><td><code>make run-bios</code> / <code>run-uefi</code></td><td>以串口 stdio 引导 ISO（BIOS / OVMF）</td></tr><tr><td><code>make run-bios-gui</code> / <code>run-uefi-gui</code></td><td>GTK 窗口让 PS/2 键盘获得真实扫描码</td></tr><tr><td><code>make run-bios-persist</code> / <code>run-uefi-persist</code></td><td>关闭 <code>-snapshot</code> 使 /etc 修改持久落在 <code>build/etc.img</code></td></tr><tr><td><code>make shot-bios</code> / <code>shot-uefi</code></td><td>VNC + monitor screendump → PNG（<code>tools/qemu_shot_vnc.py</code>）</td></tr></tbody></table><p>它们都假定 <code>build/opencube.iso</code> 已存在（<code>make iso</code>）。</p><h2 id="bug-报告要捕获什么" tabindex="-1">bug 报告要捕获什么 <a class="header-anchor" href="#bug-报告要捕获什么" aria-label="Permalink to &quot;bug 报告要捕获什么&quot;">​</a></h2><ol><li><code>boot.log</code>（会话完整的 <code>-serial file:</code> 捕获）。</li><li>若开了 <code>-d int,cpu_reset</code> 则附 <code>qemu.log</code>。</li><li>确切的 QEMU 命令行与 <code>-version</code>。</li><li>客户机内（可能时）：<code>health</code>、<code>dmesg 1024</code>、<code>crashlog</code>、 <code>dumpinfo</code>、<code>abcfg</code>（A/B 状态）、<code>update status</code>。</li></ol><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./boot-failures.html">boot-failures.md</a> — 解读引导叙事</li><li><a href="./silent-failures.html">silent-failures.md</a> — 串口回隐容错、 捕获路由</li><li><a href="./../dev/qemu-testing.html">../dev/qemu-testing.md</a> — 完整测试 工具</li><li><a href="./../dev/debugging.html">../dev/debugging.md</a> — 开发者技术</li></ul>`,47)])])}const m=a(d,[["render",n]]);export{u as __pageData,m as default};
